public String convertToPageSql(String sql, Integer offset, Integer limit) {
    // Initialize the SQL parser
    CCJSqlParserManager jSqlParser = new CCJSqlParserManager();
    Statement stmt;

    try {
        // Parse the SQL using JSqlParser
        stmt = jSqlParser.parse(new StringReader(sql));
    } catch (Throwable e) {
        // Exception handling if SQL cannot be parsed
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }

    // Ensure the statement is a SELECT statement
    if (!(stmt instanceof Select)) {
        throw new PageException("分页语句必须是Select查询!");
    }

    // Transform the SELECT statement into a paginated query
    Select select = (Select) stmt;
    String paginatedSql = createPaginatedQuery(select, offset, limit);

    return paginatedSql;
}

private String createPaginatedQuery(Select select, Integer offset, Integer limit) {
    // Transform the SELECT statement into a paginated SQL query
    StringBuilder paginatedSql = new StringBuilder(select.toString());

    // If offset is provided, add OFFSET clause
    if (offset != null && limit != null) {
        paginatedSql.append(" OFFSET ").append(offset).append(" ROWS");
        paginatedSql.append(" FETCH NEXT ").append(limit).append(" ROWS ONLY");
    }

    return paginatedSql.toString();
}

